var workspace = new LocalWorkspaceProvider(workspaceId, workspaceRoot);
ToolExecutionPolicy workspacePolicy = context -> {
    if (!context.workspace().equals(workspace.identity())) {
        return ToolExecutionPolicy.Evaluation.deny("workspace-identity");
    }
    boolean known = Set.of("read", "write", "edit", "shell").contains(context.toolName());
    if (!known) return ToolExecutionPolicy.Evaluation.deny("workspace-tool");
    return ToolExecutionPolicy.Evaluation.ask(!"read".equals(context.toolName()), "workspace-default");
};
var source = new LocalResourceSource(workspaceRoot, "workspace:" + workspaceId);
var project = new ProjectTrustStore.ProjectIdentity("project:" + workspaceId, canonicalRoot);

after.content:
var workspace = new LocalWorkspaceProvider(workspaceId, workspaceRoot);
ToolExecutionPolicy workspacePolicy = context -> {
    if (!context.workspace().equals(workspace.identity())) {
        return ToolExecutionPolicy.Evaluation.deny(
                PermissionDecider.RiskLevel.HIGH, "workspace-identity");
    }
    boolean known = Set.of("read", "write", "edit", "shell").contains(context.toolName());
    if (!known) {
        return ToolExecutionPolicy.Evaluation.deny(
                PermissionDecider.RiskLevel.HIGH, "workspace-tool");
    }
    PermissionDecider.RiskLevel risk = "read".equals(context.toolName())
            ? PermissionDecider.RiskLevel.LOW : PermissionDecider.RiskLevel.HIGH;
    return ToolExecutionPolicy.Evaluation.ask(
            !"read".equals(context.toolName()), risk, "workspace-default");
};
var source = new LocalResourceSource(workspaceRoot, "workspace:" + workspaceId);
var project = new ProjectTrustStore.ProjectIdentity("project:" + workspaceId, canonicalRoot);
